/// Where a model is in its lifecycle. Bronze: registered from a drop, not yet
/// built. Silver: the runnable archive exists (`bundle`). Gold: reserved for a
/// model whose outputs a customer consumes as an insight; not defined yet.
#[derive(Debug, Clone, Copy, PartialEq, Hash, Eq, FromRepr, Serialize, Deserialize)]
#[repr(u8)]
pub enum ModelTier {
    Bronze = 0,
    Silver = 1,
    Gold = 2,
}

impl TryFrom<u8> for ModelTier {
    type Error = crate::error::Error;
    fn try_from(v: u8) -> Result<Self, crate::error::Error> {
        ModelTier::from_repr(v).ok_or(crate::error::Error::InvalidEnumValue(v as i64))
    }
}

impl ModelTier {
    pub fn variant_name(&self) -> Option<&'static str> {
        match self {
            Self::Bronze => Some("Bronze"),
            Self::Silver => Some("Silver"),
            Self::Gold => Some("Gold"),
            _ => None,
        }
    }
}

impl From<ModelTier> for FbsModelTier {
    fn from(val: ModelTier) -> Self {
        match val {
            ModelTier::Bronze => FbsModelTier::Bronze,
            ModelTier::Silver => FbsModelTier::Silver,
            ModelTier::Gold => FbsModelTier::Gold,
        }
    }
}

impl From<FbsModelTier> for ModelTier {
    fn from(fbs: FbsModelTier) -> Self {
        match fbs.0 {
            0 => Self::Bronze,
            1 => Self::Silver,
            2 => Self::Gold,
            _ => panic!("Invalid value {} when constructing ModelTier", fbs.0),
        }
    }
}

/// A registered model, as the cortext model registry (n5) stores it: one
/// governed object per model, homed in the `.models` system directory, with
/// an ACL the owner controls and the platform's own revision history.
///
/// The object is a *reference*: the authored manifest.yaml lives in Drive as
/// its own file and is named here by id, content revision and sha256. The
/// fields a reader queries on (inputs, outputs, KPIs, ...) are projected once
/// per source revision into the `models` registry (registry.fbs), so nothing
/// on a read path opens the YAML. `silver` and `sources` are JSON documents
/// the registry records and round-trips whole (never authored by the caller).
/// The runnable-bundle pin is duplicated out of `silver` into the typed
/// `bundle` / `bundle_cid` fields so the runner resolves it without parsing.
///
/// Schema baseline. This reference shape replaced the embedded-YAML
/// `ModelManifest` without a compatible evolution (the `manifest` field
/// changed type and `tier` took a field id ahead of `bundle`). Objects
/// written in the old shape are not readable and are re-ingested, not
/// migrated; a spec version bump on the `models` registry accompanies any
/// further change to the projected fields.
#[derive(PartialEq, Debug, Clone, Hash, Eq, Serialize, Deserialize)]
pub struct ModelManifest {
    /// The registering principal (oid).
    pub authored_by: Option<String>,
    /// The silver archive's Drive file object, the runnable bundle.
    pub bundle: Option<ObjectId>,
    /// That archive's content revision at registration.
    pub bundle_cid: Option<ContentId>,
    /// The Drive file object holding manifest.yaml as authored.
    pub manifest: ObjectId,
    /// That file's content revision at registration.
    pub manifest_cid: Option<ContentId>,
    /// sha256 (hex) of the manifest bytes; the projector verifies it.
    pub manifest_sha256: String,
    /// The model's stable identity (manifest `id`); the object id is derived
    /// deterministically from it, so a re-drop revises the same object.
    pub model_id: String,
    /// JSON SilverRecord; recorded by model ingest, refused if authored.
    pub silver: Option<String>,
    /// JSON [SourceSpec] from the bundle's datacatalog.yaml.
    pub sources: Option<String>,
    /// The lifecycle tier; set by the registry, never authored.
    pub tier: ModelTier,
}

impl ModelManifest {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsModelManifest<'a>> {
        use crate::types::generated::model_manifest_generated::ModelManifestBuilder as FbsModelManifestBuilder;

        let authored_by_offset = self.authored_by.as_ref().map(|s| builder.create_string(s));
        let bundle_offset = self.bundle.as_ref().map(|o| o.serialize_to(builder));
        let bundle_cid_offset = self.bundle_cid.as_ref().map(|o| o.serialize_to(builder));
        let manifest_offset = self.manifest.serialize_to(builder);
        let manifest_cid_offset = self.manifest_cid.as_ref().map(|o| o.serialize_to(builder));
        let manifest_sha256_offset = builder.create_string(&self.manifest_sha256);
        let model_id_offset = builder.create_string(&self.model_id);
        let silver_offset = self.silver.as_ref().map(|s| builder.create_string(s));
        let sources_offset = self.sources.as_ref().map(|s| builder.create_string(s));

        let mut bldr = FbsModelManifestBuilder::new(builder);
        if let Some(offset) = authored_by_offset {
            bldr.add_authored_by(offset);
        }
        if let Some(offset) = bundle_offset {
            bldr.add_bundle(offset);
        }
        if let Some(offset) = bundle_cid_offset {
            bldr.add_bundle_cid(offset);
        }
        bldr.add_manifest(manifest_offset);
        if let Some(offset) = manifest_cid_offset {
            bldr.add_manifest_cid(offset);
        }
        bldr.add_manifest_sha256(manifest_sha256_offset);
        bldr.add_model_id(model_id_offset);
        if let Some(offset) = silver_offset {
            bldr.add_silver(offset);
        }
        if let Some(offset) = sources_offset {
            bldr.add_sources(offset);
        }
        bldr.add_tier(FbsModelTier::from(self.tier));
        bldr.finish()
    }
}

impl From<FbsModelManifest<'_>> for ModelManifest {
    fn from(fbs: FbsModelManifest<'_>) -> Self {
        let authored_by = fbs.authored_by().map(ToOwned::to_owned);
        let bundle = fbs.bundle().map(ObjectId::from);
        let bundle_cid = fbs.bundle_cid().map(ContentId::from);
        let manifest = ObjectId::from(fbs.manifest());
        let manifest_cid = fbs.manifest_cid().map(ContentId::from);
        let manifest_sha256 = fbs.manifest_sha256().to_owned();
        let model_id = fbs.model_id().to_owned();
        let silver = fbs.silver().map(ToOwned::to_owned);
        let sources = fbs.sources().map(ToOwned::to_owned);
        let tier = ModelTier::from(fbs.tier());
        Self {
            authored_by,
            bundle,
            bundle_cid,
            manifest,
            manifest_cid,
            manifest_sha256,
            model_id,
            silver,
            sources,
            tier,
        }
    }
}

impl crate::FbsSerde for ModelManifest {
    fn to_fbs_bytes(&self) -> Vec<u8> {
        let mut bldr = flatbuffers::FlatBufferBuilder::new();
        let offset = self.serialize_to(&mut bldr);
        bldr.finish_size_prefixed(offset, None);
        bldr.finished_data().to_vec()
    }

    fn from_fbs_bytes(bytes: &[u8]) -> Result<Self, flatbuffers::InvalidFlatbuffer> {
        let opts = flatbuffers::VerifierOptions {
            max_tables: 100_000_000,
            ..Default::default()
        };
        let fbs = flatbuffers::size_prefixed_root_with_opts::<FbsModelManifest>(&opts, bytes)?;
        Ok(Self::from(fbs))
    }
}

